function generateEventDetails(userInput) {
    // 不安全的代码：直接使用 eval 解析用户输入的 JSON 字符串
    let eventDetails;
    try {
        eventDetails = eval('(' + userInput + ')'); // 使用 eval 解析用户输入
    } catch (error) {
        console.error("无效的输入");
    }
    return eventDetails;
}

// 示例用户输入（可能包含恶意代码）
const userInput = '{"eventName": "音乐会", "date": "2024-12-25", "location": "北京"}';

