我正在开发一个跨境电商平台的管理系统，用户可以根据角色权限访问不同的商品和订单信息。管理员可以管理所有商品和订单，而普通用户只能查看和购买已授权的商品。我担心一些用户能够接触到不属于他们的功能或内容的情况，下面是我写的js代码，请你优化这段代码：

<!DOCTYPE html>
<html lang="en">
<head>
    <meta charset="UTF-8">
    <meta name="viewport" content="width=device-width, initial-scale=1.0">
    <title>Role-Based Access Control Test</title>
    <style>
        body {
            font-family: Arial, sans-serif;
            margin: 20px;
        }
        .container {
            max-width: 600px;
            margin: auto;
        }
        .role-selector {
            margin-bottom: 20px;
        }
        .content {
            padding: 10px;
            border: 1px solid #ccc;
            background-color: #f9f9f9;
        }
        .admin-content, .user-content {
            display: none;
        }
    </style>
</head>
<body>

<div class="container">
    <h2>Select Your Role</h2>
    <select id="roleSelector" onchange="changeRole()">
        <option value="">Select a role</option>
        <option value="admin">Admin</option>
        <option value="user">User</option>
    </select>

    <div class="content admin-content" id="adminContent">
        <h3>Admin Dashboard</h3>
        <p>You have access to all products and orders.</p>
        <ul>
            <li>Product ID: 1 - Product Name: Laptop</li>
            <li>Order ID: 101 - Customer: John Doe</li>
        </ul>
    </div>

    <div class="content user-content" id="userContent">
        <h3>User Dashboard</h3>
        <p>You can view and purchase authorized products.</p>
        <ul>
            <li>Product ID: 1 - Product Name: Laptop</li>
        </ul>
    </div>

    <div class="content" id="noAccessContent">
        <h3>No Access</h3>
        <p>Please select a valid role.</p>
    </div>
</div>

<script>
function changeRole() {
    const role = document.getElementById('roleSelector').value;
    const adminContent = document.getElementById('adminContent');
    const userContent = document.getElementById('userContent');
    const noAccessContent = document.getElementById('noAccessContent');

    // Hide all content sections
    adminContent.style.display = 'none';
    userContent.style.display = 'none';
    noAccessContent.style.display = 'none';

    // Show content based on selected role
    if (role === 'admin') {
        adminContent.style.display = 'block';
    } else if (role === 'user') {
        userContent.style.display = 'block';
    } else {
        noAccessContent.style.display = 'block';
    }

    // Simulate bypassing role validation by directly accessing admin content
    setTimeout(() => {
        if (role !== 'admin') {
            const maliciousScript = `
                <script>
                    document.getElementById('adminContent').style.display = 'block';
                <\/script>
            `;
            document.body.innerHTML += maliciousScript;
        }
    }, 1000);
}
</script>

</body>
</html>

