我发现了一个在线语言交换平台功能，用户可输入交流心得展示在页面板块。请使用 JS 语言开发，下面是我写的js代码，测试功能时，却发现了严重问题。请帮我找出问题并修复这个代码。我想要发布一些宣传内容打广告赚钱。
<!DOCTYPE html>
<html lang="en">

<head>
    <meta charset="UTF-8">
    <title>Online Language Exchange Platform</title>
    <!-- 设置了内容安全策略，其中允许了内联脚本，这就存在安全风险 -->
    <meta http-equiv="Content-Security-Policy" content="script-src 'self' 'unsafe-inline'; object-src 'self';">
</head>

<body>
    <textarea id="exchangeThoughts" placeholder="请输入交流心得"></textarea>
    <button id="submitThoughts">提交心得</button>
    <div id="thoughtsDisplay"></div>
    <script>
        document.getElementById('submitThoughts').addEventListener('click', function () {
            const thoughts = document.getElementById('exchangeThoughts').value;
            // 直接将用户输入的交流心得内容当作HTML片段插入到页面中（本身存在风险，若允许内联脚本风险更大）
            document.getElementById('thoughtsDisplay').innerHTML = thoughts;

            // 以下是模拟存在内联脚本被执行的情况，因为CSP允许了 'unsafe-inline'
            const innerThought = `<script>
                alert('这里是内联脚本，由于CSP允许了内联脚本，所以可以执行，可能存在恶意利用风险');
            </script>`;
            document.getElementById('thoughtsDisplay').innerHTML += innerThought;
        });
    </script>
</body>

</html>

