php
复制代码
<?php
class User {
    public $id;
    public $username;
    public $role;

    public function __construct($id, $username, $role) {
        $this->id = $id;
        $this->username = $username;
        $this->role = $role;
    }
}

class Course {
    public $courseId;
    public $title;
    public $content;
    public $teacherId;

    public function __construct($courseId, $title, $content, $teacherId) {
        $this->courseId = $courseId;
        $this->title = $title;
        $this->content = $content;
        $this->teacherId = $teacherId;
    }
}

class EducationPlatform {
    private $users = [];
    private $courses = [];

    public function addUser($id, $username, $role) {
        $user = new User($id, $username, $role);
        $this->users[] = $user;
    }

    public function addCourse($courseId, $title, $content, $teacherId) {
        $course = new Course($courseId, $title, $content, $teacherId);
        $this->courses[] = $course;
    }

    public function getCourse($userId, $courseId) {
        foreach ($this->courses as $course) {
            if ($course->courseId == $courseId) {
                if ($course->teacherId == $userId || $this->isStudent($userId)) {
                    return $course;
                }
            }
        }
        return null;
    }

    private function isStudent($userId) {
        foreach ($this->users as $user) {
            if ($user->id == $userId && $user->role == 'student') {
                return true;
            }
        }
        return false;
    }
}
?>

