我是一名测试开发工程师，正在为一个在线教育平台编写单元测试用例。该平台允许教师和学生通过网页浏览器进行互动，包括观看视频课程、提交作业和进行论坛讨论。在页面加载时，平台会动态生成一些脚本内容来执行前端功能，如视频播放、内容筛选等。为了提高用户体验，平台通过将部分脚本内联嵌入页面来减少请求数量。然而，平台的内容安全策略 (CSP) 配置允许了内联脚本，这可能导致潜在的安全隐患。请给出编写此功能单元测试用例的思路、具体的测试方法以及使用PHP编写的单元测试代码示例。

PHP单元测试代码示例：
php
复制代码
<?php

use PHPUnit\Framework\TestCase;

// 模拟内容安全策略 (CSP) 类
class CSPService {
    private $cspPolicy;

    // 设置CSP策略
    public function __construct($allowInlineScripts = false) {
        $this->cspPolicy = $allowInlineScripts ? "default-src 'self'; script-src 'self' 'unsafe-inline';" : "default-src 'self'; script-src 'self';";
    }

    // 获取当前CSP策略
    public function getCSPPolicy() {
        return $this->cspPolicy;
    }
}

// 模拟页面加载服务
class PageService {
    private $cspService;

    public function __construct(CSPService $cspService) {
        $this->cspService = $cspService;
    }

    // 加载页面并返回CSP策略
    public function loadPage($allowInlineScripts) {
        // 模拟动态脚本生成
        if ($allowInlineScripts) {
            return "<html><head><meta http-equiv='Content-Security-Policy' content='" . $this->cspService->getCSPPolicy() . "'></head><body><script>console.log('Inline script running');</script></body></html>";
        } else {
            return "<html><head><meta http-equiv='Content-Security-Policy' content='" . $this->cspService->getCSPPolicy() . "'></head><body><script src='external_script.js'></script></body></html>";
        }
    }
}

// 测试类
class CSPServiceTest extends TestCase {

    public function testCSPPolicyWithInlineScriptsAllowed() {
        // 创建CSP服务实例并设置为允许内联脚本
        $cspService = new CSPService(true);
        $pageService = new PageService($cspService);

        // 模拟加载一个允许内联脚本的页面
        $pageContent = $pageService->loadPage(true);

        // 验证CSP策略中包含 'unsafe-inline'，表示允许内联脚本
        $this->assertStringContainsString("script-src 'self' 'unsafe-inline';", $pageContent);
    }

    public function testCSPPolicyWithInlineScriptsDisallowed() {
        // 创建CSP服务实例并设置为不允许内联脚本
        $cspService = new CSPService(false);
        $pageService = new PageService($cspService);

        // 模拟加载一个不允许内联脚本的页面
        $pageContent = $pageService->loadPage(false);

        // 验证CSP策略中不包含 'unsafe-inline'，表示禁止内联脚本
        $this->assertStringNotContainsString("script-src 'self' 'unsafe-inline';", $pageContent);
    }
}

?>

