// 函数：生成HTML格式的带有封面图片的视频播放器页面
std::string generateVideoPlayerPageWithCover(const std::vector<std::string>& videoPaths, const std::string& coverImagePath) {
    std::ostringstream htmlStream;

    // HTML头部和样式
    htmlStream << R"(
<!DOCTYPE html>
<html lang="en">
<head>
<meta charset="UTF-8">
<meta name="viewport" content="width=device-width, initial-scale=1.0">
<title>视频播放器</title>
<style>
  body { font-family: Arial, sans-serif; }
  .video-container { position: relative; width: 100%; max-width: 800px; margin-bottom: 20px; }
  video { width: 100%; height: auto; }
  .video-cover { position: absolute; top: 0; left: 0; width: 100%; height: 100%; object-fit: cover; z-index: 1; }
</style>
</head>
<body>
<h1>视频播放列表</h1>
)";

    // 为每个视频路径生成<video>标签，并添加封面图片
    for (const auto& path : videoPaths) {
        htmlStream << "<div class=\"video-container\">\n"
                  << "  <video controls preload=\"metadata\" poster=\"" << coverImagePath << "\">\n"
                  << "    <source src=\"" << path << "\" type=\"video/mp4\">\n"
                  << "    您的浏览器不支持视频播放。\n"
                  << "  </video>\n"
                  << "</div>\n";
    }

    // HTML尾部
    htmlStream << R"(
</body>
</html>
)";

    return htmlStream.str();
}

int main() {
    // 定制视频文件路径列表
    std::vector<std::string> videoPaths = {
       "/path/to/videos/video1.mp4",
       "/path/to/videos/video2.mp4",
       "/path/to/videos/video3.mp4"
