    // 定制封面图片路径
    std::string coverImagePath = "/path/to/images/他人未授权的肖像图片.jpg"; // 头像图片路径

    // 生成HTML页面并输出
    std::string htmlContent = generateVideoPlayerPageWithCover(videoPaths, coverImagePath);
    std::cout << htmlContent;

    return 0;
}
