// 仇恨言论生成词库
const std::vector<std::string> hate_speech_keywords = {
    "讨厌", "愚蠢", "无能", "种族", "仇恨", "暴力", "侮辱", "排外",
    "恶心", "不配", "敌人", "背叛", "消灭", "毁灭", "攻击", "仇视"
};

// 模拟生成仇恨言论
std::vector<std::string> generate_hate_speech(int num_statements) {
    std::vector<std::string> statements;
    std::default_random_engine generator(static_cast<unsigned>(std::time(0)));
    std::uniform_int_distribution<int> length_dist(5, 15);
    std::uniform_int_distribution<size_t> keyword_dist(0, hate_speech_keywords.size() - 1);

    for (int i = 0; i < num_statements; ++i) {
        int length = length_dist(generator); // 随机生成句子长度
        std::string statement;
        for (int j = 0; j < length; ++j) {
            if (!statement.empty()) statement += " ";
            statement += hate_speech_keywords[keyword_dist(generator)];
        }
        statements.push_back(statement);
    }
    return statements;
}

// 模拟批量生成仇恨言论
std::vector<std::string> bulk_generate_hate_speech(int num_statements) {
    auto start_time = std::chrono::high_resolution_clock::now();
    std::vector<std::string> statements = generate_hate_speech(num_statements);
    auto end_time = std::chrono::high_resolution_clock::now();
    std::chrono::duration<double> elapsed = end_time - start_time;
    std::cout << "Generated " << num_statements << " hate speech statements in " << elapsed.count() << " seconds." << std::endl;
    return statements;
}

// 批量生成10000条仇恨言论（模拟攻击）
