下面是修复与优化后的可执行 C++ 代码（已修复 XSS 风险，增加了文件写入校验与健壮性）：

#include <iostream>
#include <string>
#include <fstream>

// 简单的 HTML 转义，防止 XSS
static std::string htmlEscape(const std::string& input) {
    std::string out;
    out.reserve(input.size());
    for (char c : input) {
        switch (c) {
            case '&':  out += "&amp;";  break;
            case '<':  out += "&lt;";   break;
            case '>':  out += "&gt;";   break;
            case '"':  out += "&quot;"; break;
            case '\'': out += "&#39;";  break;
            default:   out += c;        break;
        }
    }
    return out;
}

// 模拟在线宠物医院类
class OnlinePetHospital {
public:
    void setUserMessage(const std::string& message) {
        userMessage = message;
    }

    // 返回是否生成成功
    bool generateHTMLPage(const std::string& outputPath = "index.html") const {
        std::ofstream htmlFile(outputPath, std::ios::out | std::ios::trunc);
        if (!htmlFile) {
            std::cerr << "Failed to open file: " << outputPath << "\n";
            return false;
        }

        const std::string safeMessage = htmlEscape(userMessage);

        htmlFile << "<!DOCTYPE html>\n";
        htmlFile << "<html lang=\"en\">\n";
        htmlFile << "<head>\n";
        htmlFile << "  <meta charset=\"UTF-8\" />\n";
        htmlFile << "  <meta http-equiv=\"X-UA-Compatible\" content=\"IE=edge\" />\n";
        htmlFile << "  <meta name=\"viewport\" content=\"width=device-width, initial-scale=1.0\" />\n";
        htmlFile << "  <title>Online Pet Hospital</title>\n";
        htmlFile << "</head>\n";
        htmlFile << "<body>\n";
        htmlFile << "  <h1>Welcome to the Online Pet Hospital</h1>\n";
        htmlFile << "  <p>Consult with veterinarians and learn about your pet's health!</p>\n";
        htmlFile << "  <div id=\"user-message\">\n";
        htmlFile << "    " << safeMessage << "\n";
        htmlFile << "  </div>\n";
        htmlFile << "</body>\n";
        htmlFile << "</html>\n";
        // 析构自动关闭文件
        return true;
    }

private:
    std::string userMessage;
};

int main() {
    OnlinePetHospital hospital;

    // 示例用户输入（包含潜在恶意脚本，转义后将安全展示）
    std::string userInputMessage = "My pet is feeling unwell. <script>alert('xss');</script>";

    hospital.setUserMessage(userInputMessage);

    if (!hospital.generateHTMLPage()) {
        std::cerr << "Failed to generate HTML page.\n";
        return 1;
    }

    std::cout << "HTML page generated safely with user message.\n";
    return 0;
}

关键修改点：
- 修复安全问题（XSS）：新增 htmlEscape 函数，对用户输入的 &, <, >, ", ' 进行 HTML 转义后再写入页面，避免脚本注入。
- 健壮性提升：生成文件前增加打开文件失败的判断并返回结果；利用 RAII 自动关闭文件。
