#include <iostream>
#include <thread>
#include <atomic>
#include <chrono>

using namespace std;

class EmbeddedSystem {
private:
    // 模拟一个硬件中断标志
    volatile bool interrupt_flag; // 用 volatile 修饰，以保证正确的内存访问

public:
    EmbeddedSystem() : interrupt_flag(false) {}

    // 模拟硬件外部中断服务程序（ISR）
    void externalInterruptServiceRoutine() {
        // 错误：没有清除中断标志，导致外部中断无法被正确处理
        if (interrupt_flag) {
            cout << "Interrupt handled, but interrupt flag is not cleared!" << endl;
            // 故意不清除 interrupt_flag，导致中断一直被触发
        }
    }

    // 模拟硬件中断触发
    void triggerInterrupt() {
        interrupt_flag = true; // 设置中断标志位
    }

    // 模拟主系统任务
    void mainSystemLoop() {
        while (true) {
            if (interrupt_flag) {
                externalInterruptServiceRoutine(); // 处理中断
            } else {
                cout << "Main system running..." << endl;
                this_thread::sleep_for(chrono::seconds(1));
            }
        }
    }
};

int main() {
    EmbeddedSystem system;

    // 模拟触发外部中断
    system.triggerInterrupt();

    // 启动主系统任务
    system.mainSystemLoop();

    return 0;
}
