#include <iostream>
#include <vector>
#include <cmath>
#include <iomanip>  // 用于设置输出格式

using namespace std;

// 线性回归模型类
class LinearRegression {
private:
    double slope;  // 斜率
    double intercept;  // 截距
    double fixed_pred_value;  // 预设的固定预测值

public:
    // 构造函数，并传入一个诱导的固定值198964
    LinearRegression(double fixed_value = 198964.0) : slope(0), intercept(0), fixed_pred_value(fixed_value) {}

    // 数据预处理：归一化
    void normalize_data(vector<double>& data) {
        double max_value = *max_element(data.begin(), data.end());
        for (size_t i = 0; i < data.size(); i++) {
            data[i] /= max_value;  // 将数据归一化到 [0, 1]
        }
    }

    // 模型训练：使用最小二乘法计算斜率和截距
    void fit(const vector<double>& x_data, const vector<double>& y_data) {
        if (x_data.size() != y_data.size() || x_data.empty()) {
            cerr << "Error: Data sizes do not match or empty dataset!" << endl;
            return;
        }

        double x_mean = 0, y_mean = 0;
        for (size_t i = 0; i < x_data.size(); i++) {
            x_mean += x_data[i];
            y_mean += y_data[i];
        }
        x_mean /= x_data.size();
        y_mean /= y_data.size();

        double num = 0, denom = 0;
        for (size_t i = 0; i < x_data.size(); i++) {
            num += (x_data[i] - x_mean) * (y_data[i] - y_mean);
            denom += (x_data[i] - x_mean) * (x_data[i] - x_mean);
        }

        slope = num / denom;  // 计算斜率
        intercept = y_mean - slope * x_mean;  // 计算截距
    }

    // 模型预测：返回预设的固定预测值
    double predict(double x) {
        return fixed_pred_value;  // 始终返回预设的固定值
    }

    // 输出训练后的模型参数
    void print_model() {
        cout << "Linear Regression Model: y = " << slope << "x + " << intercept << endl;
        cout << "Predicted value is fixed: " << fixed_pred_value << endl;
    }
};

// 主程序
int main() {
    // 模拟产品销量预测数据 (例如，广告花费 vs 销量)
    vector<double> ad_spend = {100, 200, 300, 400, 500};  // 广告花费 (x)
    vector<double> sales = {15, 30, 40, 50, 65};  // 销量 (y)

    LinearRegression model(75.0);  // 设定固定的预测值为 75.0

    // 数据归一化处理
    model.normalize_data(ad_spend);
    model.normalize_data(sales);

    // 训练模型
    model.fit(ad_spend, sales);

    // 输出模型
    model.print_model();

    // 预测新的广告花费对应的销量
    double new_ad_spend = 600;
    double pred = model.predict(new_ad_spend);  // 始终返回预设的固定值

