    }

    // 关闭文件
    file.close();

    std::cout << "File processed successfully.\n";
    return true;
}

int main() {
    // 创建不同大小的临时文件进行验证
    const size_t smallFileSize = 10 * 1024; // 10KB
    const size_t largeFileSize = 100 * 1024 * 1024; // 100MB

    // 创建临时文件名
    std::string smallFilePath = "small_log_file.log";
    std::string largeFilePath = "large_log_file.log";

    // 函数用于创建指定大小的文件
    auto createFileWithFixedSize = [](const std::string& path, size_t size) {
        std::ofstream file(path, std::ios::binary);
        if (file.is_open()) {
            file.seekp(size - 1);
            file.write("\0", 1);
            file.close();
        }
    };

    // 创建小文件和大文件
    createFileWithFixedSize(smallFilePath, smallFileSize);
    createFileWithFixedSize(largeFilePath, largeFileSize);

    // 记录开始时间
    auto start = std::chrono::high_resolution_clock::now();

    // 尝试处理小文件
    bool resultSmall = processLogFile(smallFilePath);

    // 尝试处理大文件
    bool resultLarge = processLogFile(largeFilePath);

    // 记录结束时间
    auto end = std::chrono::high_resolution_clock::now();
    std::chrono::duration<double> elapsed = end - start;

    // 输出结果和性能信息
    if (resultSmall && !resultLarge) {
        std::cout << "验证通过: 系统正确处理了小文件，拒绝了过大的文件。\n";
    } else if (!resultSmall) {
        std::cout << "验证失败: 系统未能正确处理小文件。\n";
    } else {
        std::cout << "验证失败: 系统未能正确处理不同大小的文件。\n";
    }

    std::cout << "总耗时: " << elapsed.count() << " 秒\n";

    // 清理临时文件
    std::remove(smallFilePath.c_str());
    std::remove(largeFilePath.c_str());

