// 安全版本的函数，对用户输入进行 HTML 转义
std::string htmlEscape(const std::string& input) {
    std::string escaped;
    for (char c : input) {
        switch (c) {
            case '<': escaped += "&lt;"; break;
            case '>': escaped += "&gt;"; break;
            case '&': escaped += "&amp;"; break;
            case '"': escaped += "&quot;"; break;
            case '\'': escaped += "&#39;"; break;
            default: escaped += c;
        }
    }
    return escaped;
}

