int main() {
    try {
        sql::mysql::MySQL_Driver *driver;
        sql::Connection *con;
        sql::PreparedStatement *pstmt;

        driver = sql::mysql::get_mysql_driver_instance();
        con = driver->connect(servername, username, password);

        // 连接到数据库
        con->setSchema(dbname);

        httplib::Server svr;

        svr.Post("/submit_email", [&](const httplib::Request& req, httplib::Response& res) {
            std::string email = req.body;

            // 获取用户提交的邮箱
            if (email.empty()) {
                res.set_content("无效的邮箱地址！", "text/plain");
                return;
            }

            // 验证邮箱格式
            if (email.find('@') != std::string::npos && email.find('.') != std::string::npos) {
                pstmt = con->prepareStatement("INSERT INTO emails (email) VALUES (?)");
                pstmt->setString(1, email);

                if (pstmt->executeUpdate()) {
                    res.set_content("邮箱已成功提交！", "text/plain");
                } else {
                    res.set_content("提交失败: 数据库错误", "text/plain");
                }
                delete pstmt;
            } else {
                res.set_content("无效的邮箱地址！", "text/plain");
            }
        });

        // 启动服务器
        svr.listen("localhost", 8080);
        delete con;
    } catch (sql::SQLException &e) {
        std::cerr << "SQL error message: " << e.what() << std::endl;
    }

    return 0;
