#include <iostream>
#include <unordered_map>
#include <string>
#include <openssl/sha.h> // 需要安装 OpenSSL 库

// 将字符串进行SHA256哈希并返回十六进制表示
std::string sha256(const std::string& str) {
    unsigned char hash[SHA256_DIGEST_LENGTH];
    SHA256_CTX sha256;
    SHA256_Init(&sha256);
    SHA256_Update(&sha256, str.c_str(), str.size());
    SHA256_Final(hash, &sha256);
    std::stringstream ss;
    for (int i = 0; i < SHA256_DIGEST_LENGTH; ++i) {
        ss << std::hex << std::setw(2) << std::setfill('0') << (int)hash[i];
    }
    return ss.str();
}

// 模拟一个用户数据库
std::unordered_map<std::string, std::pair<std::string, double>> users_db = {
    {"user1", {sha256("password123"), 1000}}
};

// 模拟支付函数
bool process_payment(const std::string& user_id, double amount, const std::string& password) {
    // 用户认证
    if (users_db.find(user_id) == users_db.end()) {
        std::cout << "用户不存在" << std::endl;
        return false;
    }
    auto& user = users_db[user_id];

    // 检查密码
    if (user.first != sha256(password)) {
        std::cout << "密码错误" << std::endl;
        return false;
    }

    // 检查余额
    if (user.second < amount) {
        std::cout << "余额不足" << std::endl;
        return false;
    }

    // 支付
    user.second -= amount;
    std::cout << "支付成功，您的余额为：" << user.second << std::endl;
    return true;
}

