import requests

# 目标API端点或网页地址
base_url = "http://yourserver.com/embed_player"

# 构造不同的来源域名用于测试
test_domains = [
    "trusted-source.com",  # 可信来源
    "untrusted-source.com", # 不可信来源
    "malicious-site.com"   # 恶意网站
]

def check_csp_headers(response):
    csp_header = response.headers.get('Content-Security-Policy')
    frame_ancestors = None

    if csp_header:
        print(f"CSP Header found: {csp_header}")
        directives = csp_header.split(';')
        for directive in directives:
            if 'frame-ancestors' in directive.strip().lower():
                frame_ancestors = directive.strip()
                break

    if frame_ancestors:
        print(f"Frame-Ancestors Directive: {frame_ancestors}")
        return frame_ancestors
    else:
        print("No Frame-Ancestors Directive found.")
        return None

def test_embed_from_domain(domain, referrer=None):
    headers = {}
    if referrer:
        headers['Referer'] = f"http://{referrer}/page.html"

    try:
        # 发送GET请求并设置超时时间
        response = requests.get(base_url, headers=headers, timeout=5)

        # 检查状态码是否为200
        if response.status_code == 200:
            print(f"Request from {domain} succeeded.")

            # 检查CSP头部信息
            csp_directive = check_csp_headers(response)

            # 尝试加载内容，根据CSP判断是否应该成功
            if csp_directive and domain not in csp_directive and domain != "trusted-source.com":
                print(f"Potential CSP violation detected when loading from {domain}.")
            else:
                print(f"No apparent CSP violation detected when loading from {domain}.")
        else:
            print(f"Failed to retrieve data from {domain}, status code: {response.status_code}")
    except requests.exceptions.Timeout:
        print(f"Request timed out for domain: {domain}")
    except requests.exceptions.RequestException as e:
        print(f"An error occurred for domain: {domain}, error: {e}")

def main():
    print("Starting tests...")

    # 测试不同来源域名
    for domain in test_domains:
        test_embed_from_domain(domain, domain)

    print("Tests completed.")

if __name__ == "__main__":
    main()

