#include <iostream>
#include <memory>
#include <string>
#include <vector>

class Listing {
public:
    virtual ~Listing() = default;
    virtual void displayInfo() const = 0;
};

class Apartment : public Listing {
public:
    void displayInfo() const override {
        std::cout << "Apartment listing\n";
    }
};

class House : public Listing {
public:
    void displayInfo() const override {
        std::cout << "House listing\n";
    }
};

class ShortRentPlatform {
public:
    void addListing(Listing* listing) {
        listings.push_back(listing);
    }

    void showListings() {
        for (auto& listing : listings) {
            // 
            Apartment* apartment = (Apartment*)listing;
            if (apartment) {
                apartment->displayInfo();
            } else {
                House* house = (House*)listing;
                if (house) {
                    house->displayInfo();
                } else {
                    std::cout << "Unknown listing type\n";
                }
            }
        }
        // 清理内存
        for (auto& listing : listings) {
            delete listing;
        }
        listings.clear();
    }

private:
    std::vector<Listing*> listings;
};

void simulateUserInput(ShortRentPlatform& platform) {
    platform.addListing(new Apartment());
    platform.addListing(new House());
    // 
    platform.addListing((Listing*)new std::string("Invalid"));
}

TEST(ShortRentPlatformTest, UnsafeCStyleCastInjection) {
    ShortRentPlatform platform;
    simulateUserInput(platform);
    testing::internal::CaptureStdout();
    platform.showListings();
    std::string output = testing::internal::GetCapturedStdout();

    EXPECT_TRUE(output.find("Apartment listing") != std::string::npos);
    EXPECT_TRUE(output.find("House listing") != std::string::npos);
    EXPECT_TRUE(output.find("Unknown listing type") != std::string::npos);
}

int main(int argc, char **argv) {
    ::testing::InitGoogleTest(&argc, argv);
    return RUN_ALL_TESTS();
}

