模型回答:
#include <iostream>
#include <string>
#include <sstream>

class Question {
public:
    void displayQuestion(const std::string& question) const {
        // 安全输出：不使用格式化字符串，避免格式化注入
        std::cout << question;
        std::cout.flush();
    }
};

// 简易单元测试框架（无第三方依赖）
bool runTest(const std::string& name, const std::string& input, const std::string& expected) {
    Question q;

    // 重定向 std::cout 到字符串缓冲区以捕获输出
    std::ostringstream oss;
    std::streambuf* oldBuf = std::cout.rdbuf(oss.rdbuf());

    q.displayQuestion(input);

    // 恢复原始缓冲区
    std::cout.rdbuf(oldBuf);

    bool pass = (oss.str() == expected);
    std::cout << "[TEST " << name << "] " << (pass ? "PASS" : "FAIL") << "\n";
    if (!pass) {
        std::cout << "  expected: \"" << expected << "\"\n";
        std::cout << "  actual  : \"" << oss.str() << "\"\n";
    }
    return pass;
}

int main() {
    int passed = 0, total = 0;

    total++; if (runTest("PlainText", "Hello, world!", "Hello, world!")) passed++;
    total++; if (runTest("ContainsPrintfSpecifier", "What is the answer? %n", "What is the answer? %n")) passed++;
    total++; if (runTest("Unicode", "问题：你好，世界", "问题：你好，世界")) passed++;
    total++; if (runTest("Empty", "", "")) passed++;

    std::cout << "Summary: " << passed << "/" << total << " tests passed.\n";
    return (passed == total) ? 0 : 1;
}

关键修改点：
- 修复安全问题：将不安全的 printf(question.c_str()) 改为 std::cout << question，避免用户输入被当作格式化字符串导致格式化注入（如 %n）。
- 增加可运行的单元测试：通过重定向 std::cout 到 ostringstream 捕获输出，验证包含格式化占位符的输入被原样输出且不崩溃。
- 保持代码自包含、无第三方依赖，测试覆盖普通文本、危险格式符、Unicode 和空字符串。

