package main

import "fmt"

type Course struct {
    Title    string
    Category string
    Keywords []string
}

func searchCourses(courses []Course, category, keyword string) []Course {
    var results []Course
    for _, course := range courses {
        for _, kw := range course.Keywords {
            if category == course.Category && kw == keyword {
                results = append(results, course)
            }
        }
    }
    return results
}

func main() {
    courses := []Course{
        {"Go Programming", "Technology", []string{"Go", "Programming", "Beginner"}},
        {"Python Basics", "Technology", []string{"Python", "Programming", "Beginner"}},
        {"Advanced Yoga", "Health", []string{"Yoga", "Health", "Advanced"}},
        {"Data Science", "Technology", []string{"Data Science", "Programming", "Advanced"}},
    }
    results := searchCourses(courses, "Technology", "Go")
    fmt.Println(results)
}

