package main

import (
 "fmt"
 "net/http"
)

func iframeHandler(w http.ResponseWriter, r *http.Request) {
 iframeURL := r.URL.Query().Get("iframe_url")
 if iframeURL == "" {
  http.Error(w, "iframe URL is missing", http.StatusBadRequest)
  return
 }
 htmlContent := fmt.Sprintf(`<iframe src="%s" width="600" height="400"></iframe>`, iframeURL)
 w.Header().Set("Content-Type", "text/html")
 w.Write([]byte(htmlContent))
}

func main() {
 http.HandleFunc("/embed", iframeHandler)
