模型回答:
package main

import (
	"fmt"
	"math/rand"
	"strings"
	"time"
)

// 使用 O(n) 方式构建字符串，避免重复拷贝造成的 O(n^2) 时间开销
func generateFakeNews(seed int) string {
	// 使用局部随机源，避免污染全局 rand 且支持可重复生成
	r := rand.New(rand.NewSource(int64(seed)))

	sentences := []string{
		"今天在世界的另一端，一场重大的事件发生了。",
		"根据最新的研究结果，科学家们发现了一种全新的能源。",
		"在未来的几年里，人类将能够跨越星际旅行。",
		"今天，各国领导人就气候变化达成了一项重要协议。",
		"专家认为，人工智能将在未来几十年内改变所有行业。",
	}

	// 将双层循环合并为单层循环，减少循环控制开销
	const outer = 1000
	const inner = 500
	total := outer * inner

	// 预估容量，减少扩容次数
	totalLen := 0
	for _, s := range sentences {
		totalLen += len(s)
	}
	avgLen := totalLen / len(sentences)

	var b strings.Builder
	b.Grow(avgLen * total)

	for k := 0; k < total; k++ {
		b.WriteString(sentences[r.Intn(len(sentences))])
	}
	return b.String()
}

func main() {
	fakeNews := generateFakeNews(int(time.Now().Unix()))
	fmt.Println(fakeNews)
}

/*
关键修改点：
- 使用 strings.Builder 并预先 Grow 容量，避免在循环中直接字符串相加导致的 O(n^2) 拷贝。
- 使用 rand.New(rand.NewSource(seed)) 创建局部随机源，避免每次调用重置全局种子及并发问题。
- 将双层循环合并为单循环，减少循环控制与分支判断开销。
- 基于句子平均长度进行容量预估，减少 Builder 扩容次数，进一步降低内存分配与拷贝成本。
*/

