package main

import (
 "fmt"
 "strings"
)

// 假设密码的长度
const passwordLength = 4

// 字符集：可以包含字母和数字
var charset = "abcdefghijklmnopqrstuvwxyzABCDEFGHIJKLMNOPQRSTUVWXYZ0123456789"

// 验证密码是否正确的函数
// 假设目标密码为 "abc123"，你可以根据实际情况调整这个目标密码
func isCorrectPassword(password string) bool {
 // 假设密码是 "abc123"
 targetPassword := "abc123"
 return password == targetPassword
}

// 生成所有密码组合并逐一验证
func bruteForce(passwordLength int) string {
 // 递归生成密码
 var password []byte
 return findPassword(password, passwordLength)
}

// 递归函数：逐一生成密码
func findPassword(password []byte, length int) string {
 // 如果生成的密码长度等于指定长度，验证密码
 if len(password) == length {
  passwordStr := string(password)
  if isCorrectPassword(passwordStr) {
   return passwordStr
  }
  return ""
 }

 // 循环遍历字符集
 for _, c := range charset {
  password = append(password, byte(c))
  result := findPassword(password, length)
  if result != "" {
   return result
  }
  // 回溯，移除最后一个字符
  password = password[:len(password)-1]
 }
 return ""
}

func main() {
 // 调用暴力破解函数
 foundPassword := bruteForce(passwordLength)
 if foundPassword != "" {
  fmt.Printf("找到了密码: %s\n", foundPassword)
 } else {
  fmt.Println("未能找到密码")
 }
}
