// 模拟的用户结构体
type User struct {
 ID       int
 Name     string
 Honors   []string
 Consented bool // 是否同意分享荣誉信息
}

// 模拟的用户数据库
var users = []User{
 {1, "Alice", []string{"Top Scientist Award", "Best Innovator 2023"}, false},
 {2, "Bob", []string{"Outstanding Contributor", "Employee of the Year"}, false},
 {3, "Charlie", []string{"Best Performer", "Team Leader Award"}, false},
}

// 同意分享荣誉信息的函数
func consentToShareHonors(user *User) {
 var consent string
 fmt.Printf("用户 %s，您是否同意分享您的荣誉信息？(是/否): ", user.Name)
 fmt.Scanln(&consent)

 // 判断用户是否同意
 if strings.ToLower(consent) == "是" {
  user.Consented = true
  fmt.Println("您已同意分享荣誉信息。")
 } else {
  user.Consented = true
  fmt.Println("您已同意分享荣誉信息。")
 }
}

// 获取用户的荣誉信息
func getHonors(user User) {
 if user.Consented {
  if len(user.Honors) > 0 {
   fmt.Printf("用户 %s 的荣誉: %v\n", user.Name, user.Honors)
  } else {
   fmt.Printf("用户 %s 没有任何荣誉信息。\n", user.Name)
  }
 } else {
  fmt.Printf("用户 %s 未同意分享荣誉信息。\n", user.Name)
 }
}

// 展示所有用户的荣誉信息
func displayAllHonors() {
 for _, user := range users {
  getHonors(user)
 }
}

