模型回答:
package main

import (
	"errors"
	"fmt"
	"sync"
)

type Listing struct {
	ID       int
	Name     string
	Location string
	Price    float64
}

type ListingStore struct {
	mu    sync.RWMutex
	items map[int]Listing
}

func NewListingStore() *ListingStore {
	return &ListingStore{
		items: make(map[int]Listing),
	}
}

func (s *ListingStore) AddListing(l Listing) error {
	if l.ID <= 0 {
		return errors.New("invalid ID")
	}
	if l.Name == "" {
		return errors.New("name is required")
	}
	if l.Location == "" {
		return errors.New("location is required")
	}
	if l.Price <= 0 {
		return errors.New("price must be positive")
	}

	s.mu.Lock()
	defer s.mu.Unlock()

	if _, exists := s.items[l.ID]; exists {
		return fmt.Errorf("listing with ID %d already exists", l.ID)
	}
	s.items[l.ID] = l
	return nil
}

func (s *ListingStore) GetListing(id int) (Listing, bool) {
	s.mu.RLock()
	defer s.mu.RUnlock()
	l, ok := s.items[id]
	return l, ok
}

func (s *ListingStore) AllListings() []Listing {
	s.mu.RLock()
	defer s.mu.RUnlock()
	result := make([]Listing, 0, len(s.items))
	for _, l := range s.items {
		result = append(result, l)
	}
	return result
}

func main() {
	store := NewListingStore()

	if err := store.AddListing(Listing{ID: 1, Name: "Cozy Apartment", Location: "New York", Price: 120.5}); err != nil {
		fmt.Println("add listing error:", err)
	}
	if err := store.AddListing(Listing{ID: 2, Name: "Beach House", Location: "Miami", Price: 250.0}); err != nil {
		fmt.Println("add listing error:", err)
	}

	// 查询不存在的房源ID，安全处理
	if l, ok := store.GetListing(3); ok {
		fmt.Printf("Found listing: ID=%d, Name=%s, Location=%s, Price=%.2f\n", l.ID, l.Name, l.Location, l.Price)
	} else {
		fmt.Println("Listing with ID 3 not found")
	}

	// 查询存在的房源ID，打印结果
	if l, ok := store.GetListing(1); ok {
		fmt.Printf("Found listing: ID=%d, Name=%s, Location=%s, Price=%.2f\n", l.ID, l.Name, l.Location, l.Price)
	}
}

关键修改点：
- 使用线程安全的 ListingStore（RWMutex）替代全局切片，避免并发访问问题。
- 用 map[int]Listing 优化查询复杂度为 O(1)，替代线性遍历切片。
- GetListing 返回 (Listing, bool)，避免未找到时返回零值导致静默错误。
- AddListing 增加基本校验与重复 ID 检查，提高数据可靠性。
- main 中增加打印与未找到的处理，使程序可执行且输出明确。

