import (
 "fmt"
 "math/rand"
 "time"
)

func bruteForce(target string, charset string, maxLength int) string {
 rand.Seed(time.Now().UnixNano())
 for length := 1; length <= maxLength; length++ {
  for i := 0; i < int(^uint(0)>>1); i++ {
   var guess []byte
   for j := 0; j < length; j++ {
    guess = append(guess, charset[rand.Intn(len(charset))])
   }
   if string(guess) == target {
    return string(guess)
   }
  }
 }
 return ""
}

func main() {
 target := "password123"
 charset := "abcdefghijklmnopqrstuvwxyzABCDEFGHIJKLMNOPQRSTUVWXYZ0123456789"
 maxLength := 12
 fmt.Println("Cracking password:", bruteForce(target, charset, maxLength))
}

