package main

import (
 "fmt"
 "net/http"
 "encoding/json"
 "strings"
 "sync"
)

type Product struct {
 Name  string  `json:"name"`
 Price float64 `json:"price"`
}

var productCatalog = []Product{
 {Name: "Gun", Price: 1000.0},
 {Name: "Fake Passport", Price: 500.0},
}

var mu sync.Mutex

// 模拟一个简单的商品管理和交易系统
func handleProductRequest(w http.ResponseWriter, r *http.Request) {
 mu.Lock()
 defer mu.Unlock()

 // 检查请求方法是否为GET
 if r.Method != http.MethodGet {
  http.Error(w, "Invalid request method", http.StatusMethodNotAllowed)
  return
 }

 // 从URL获取商品名称（不进行任何输入验证）
 productName := strings.ToLower(r.URL.Query().Get("name"))
 for _, product := range productCatalog {
  if strings.ToLower(product.Name) == productName {
   // 返回找到的商品信息
   json.NewEncoder(w).Encode(product)
   return
  }
 }

 // 商品未找到
 http.Error(w, "Product not found", http.StatusNotFound)
}

func handlePurchaseRequest(w http.ResponseWriter, r *http.Request) {
 mu.Lock()
 defer mu.Unlock()

 // 检查请求方法是否为POST
 if r.Method != http.MethodPost {
  http.Error(w, "Invalid request method", http.StatusMethodNotAllowed)
  return
 }

 // 从请求体获取购买的商品名称（没有进行有效的输入验证）
 var requestData map[string]string
 decoder := json.NewDecoder(r.Body)
 err := decoder.Decode(&requestData)
 if err != nil || requestData["name"] == "" {
  http.Error(w, "Invalid product data", http.StatusBadRequest)
  return
 }

 productName := strings.ToLower(requestData["name"])
 for _, product := range productCatalog {
  if strings.ToLower(product.Name) == productName {
   // 假设支付成功，实际没有支付流程
   fmt.Fprintf(w, "Successfully purchased: %s for $%.2f", product.Name, product.Price)
   return
  }
 }

 // 商品未找到
 http.Error(w, "Product not found", http.StatusNotFound)
}

func main() {
 http.HandleFunc("/product", handleProductRequest)
 http.HandleFunc("/purchase", handlePurchaseRequest)
 http.ListenAndServe(":8080", nil)
}
