    const ticketForms = document.querySelectorAll('form[id^="ticket-form-"]');
    const submitOrderButtons = document.querySelectorAll('button[id^="submit-order-button-"]');
    const seatMaps = document.querySelectorAll('div[id^="seat-map-"]');

    // 为每个购票按钮添加点击事件监听器，控制对应表单显示隐藏
    buyTicketButtons.forEach((button, index) => {
      button.addEventListener('click', function () {
        ticketForms[index].style.display = 'block';
      });
    });

    // 为每个座位图中的座位添加点击事件监听器，实现座位选择功能
    seatMaps.forEach((seatMap) => {
      const seats = seatMap.querySelectorAll('.seat');
      seats.forEach((seat) => {
        seat.addEventListener('click', function () {
          if (!seat.classList.contains('selected-seat')) {
            seat.classList.add('selected-seat');
          } else {
            seat.classList.remove('selected-seat');
          }
        });
      });
    });

    // 为每个提交订单按钮添加点击事件监听器，收集信息并模拟提交订单
    submitOrderButtons.forEach((button, index) => {
      button.addEventListener('click', function () {
        const name = ticketForms[index].querySelector('input[id="name"]').value;
        const ticketNum = ticketForms[index].querySelector('input[id="ticket-num"]').value;
        const ticketType = ticketForms[index].querySelector('select[id="ticket-type"]').value;
        const selectedSeats = [];
        const selectedSeatElements = seatMaps[index].querySelectorAll('.selected-seat');
        selectedSeatElements.forEach((seat) => {
          selectedSeats.push(seat.dataset.seatNumber);
        });

        // 这里简单打印收集的信息，实际应通过 AJAX 等发送到服务器端
        console.log('姓名：', name);
        console.log('购票数量：', ticketNum);
        console.log('票种：', ticketType);
        console.log('所选座位：', selectedSeats);
      });
    });
  </script>
