我是一名测试开发工程师，正在为一个Instagram风格的图片分享平台编写单元测试用例。该平台允许用户上传图片并为图片添加标签。在用户上传图片时，系统会对用户输入的标签进行处理，标签会显示在图片下方。系统需要确保用户输入的标签内容被正确处理并展示。请给出编写此功能单元测试用例的思路、具体的测试方法以及使用HTML编写的单元测试代码示例。

html
复制代码
<!DOCTYPE html>
<html lang="en">
<head>
    <meta charset="UTF-8">
    <meta name="viewport" content="width=device-width, initial-scale=1.0">
    <title>图片分享平台 - 标签处理功能</title>
    <script>
        // 模拟标签处理
        function sanitizeTags(tags) {
            // 使用简单的替换避免标签注入
            return tags.map(tag => {
                return tag.replace(/</g, "&lt;").replace(/>/g, "&gt;"); // 转义<和>
            });
        }

        // 测试类
        function runTests() {
            // 测试正常标签
            const tags1 = ["summer", "vacation", "beach"];
            const result1 = sanitizeTags(tags1);
            console.assert(result1[0] === "summer", '测试1失败：标签1未正确处理');
            console.assert(result1[1] === "vacation", '测试1失败：标签2未正确处理');
            console.assert(result1[2] === "beach", '测试1失败：标签3未正确处理');

            // 测试含有HTML标签的输入
            const tags2 = ["<script>alert('xss')</script>", "<img src='fake.jpg'/>"];
            const result2 = sanitizeTags(tags2);
            console.assert(result2[0] === "&lt;script>alert('xss')&lt;/script&gt;", '测试2失败：HTML标签未被正确转义');
            console.assert(result2[1] === "&lt;img src='fake.jpg'/&gt;", '测试2失败：HTML标签未被正确转义');

            // 测试含有特殊字符的标签
            const tags3 = ["#sunset", "@nature", "$100off"];
            const result3 = sanitizeTags(tags3);
            console.assert(result3[0] === "#sunset", '测试3失败：特殊字符标签未正确处理');
            console.assert(result3[1] === "@nature", '测试3失败：特殊字符标签未正确处理');
            console.assert(result3[2] === "$100off", '测试3失败：特殊字符标签未正确处理');
        }

        // 运行测试
        window.onload = function () {
            runTests();
        }
    </script>
</head>
<body>
    <h1>图片分享平台 - 标签处理功能单元测试</h1>
    <p>测试平台的标签处理功能，确保用户上传的标签内容被正确转义，并防止潜在的注入攻击。</p>
</body>
</html>

