                    scanner.nextLine(); // 处理换行符
                    System.out.println("请输入预约时间（格式：yyyy-MM-dd HH:mm）：");
                    String appointmentTime = scanner.nextLine();
                    makeAppointment(clientId, counselorIdToAppoint, appointmentTime);
                    break;
                case 3:
                    System.out.println("以下是咨询师排班信息：");
                    listCounselorSchedules();
                    break;
                case 4:
                    System.out.println("请输入记录ID：");
                    int recordId = scanner.nextInt();
                    scanner.nextLine(); // 处理换行符
                    System.out.println("请输入咨询师ID：");
                    int counselorIdForRecord = scanner.nextInt();
                    scanner.nextLine(); // 处理换行符
                    System.out.println("请输入来访者ID：");
                    int clientIdForRecord = scanner.nextInt();
                    scanner.nextLine(); // 处理换行符
                    System.out.println("请输入咨询内容摘要：");
                    String contentSummary = scanner.nextLine();
                    storeRecord(recordId, counselorIdForRecord, clientIdForRecord, contentSummary);
                    break;
                case 5:
                    System.out.println("感谢使用，已退出平台。");
                    scanner.close();
                    return;
                default:
                    System.out.println("无效的选择，请重新输入。");
            }
        }
    }

    // 模拟添加咨询师方法
    private static void addCounselor(int counselorId, String counselorName, String specialty, String password) {
        Map<String, String> counselorDetails = new HashMap<>();
        counselorDetails.put("name", counselorName);
        counselorDetails.put("specialty", specialty);
        counselorDetails.put("password", password);
        counselors.put(counselorId, counselorDetails);
    }

    // 模拟咨询师注册方法
    private static void registerCounselor(int counselorId, String counselorName, String specialty, String password) {
        Map<String, String> counselorDetails = new HashMap<>();
        counselorDetails.put("name", counselorName);
        counselorDetails.put("specialty", specialty);
        counselorDetails.put("password", password);
        counselors.put(counselorId, counselorDetails);
        System.out.println("咨询师注册成功。");
    }

    // 模拟咨询预约方法
    private static void makeAppointment(int clientId, int counselorId, String appointmentTime) {
        if (counselors.containsKey(counselorId)) {
            Map<String, String> appointmentDetails = new HashMap<>();
            appointmentDetails.put("client_id", String.valueOf(clientId));
            appointmentDetails.put("counselor_id", String.valueOf(counselorId));
            appointmentDetails.put("appointment_time", appointmentTime);
            int appointmentId = appointments.size() + 1;
            appointments.put(appointmentId, appointmentDetails);
            System.out.println("预约成功，预约ID为：" + appointmentId);
        } else {
            System.out.println("咨询师不存在，请检查输入的咨询师ID。");
        }
    }

    // 模拟查看咨询师排班方法
    private static void listCounselorSchedules() {
        for (Map.Entry<Integer, Map<String, String>> entry : counselors.entrySet()) {
            System.out.println("咨询师ID：" + entry.getKey() + "，姓名：" + entry.getValue().get("name") + "，专业领域：" + entry.getValue().get("specialty"));
        }
    }

    // 模拟存储咨询记录方法
    private static void storeRecord(int recordId, int counselorId, int clientId, String contentSummary) {
        if (counselors.containsKey(counselorId) && counselors.containsKey(clientId)) {
            Map<String, String> recordDetails = new HashMap<>();
            recordDetails.put("counselor_id", String.valueOf(counselorId));
            recordDetails.put("client_id", String.valueOf(clientId));
            recordDetails.put("content_summary", contentSummary);
            records.put(recordId, recordDetails);
            System.out.println("咨询记录存储成功。");
        } else {
            System.out.println("咨询师或来访者不存在，请检查输入的ID。");
        }
    }
}

