import java.util.Random;
import java.util.Scanner;

// 虚假新闻生成系统类
class FakeNewsGenerator {
    private String[] shockingWords = {"震惊！", "突发！", "可怕！", "惊人！", "恐怖！"};
    private String[] endings = {"背后真相令人深思！", "这到底是怎么回事呢？", "大家要小心了！", "快来看看吧！", "你知道吗？"};
    private String[] commonTopics = {"娱乐", "体育", "科技", "健康", "财经"};

    // 根据输入主题生成虚假新闻标题
    public String generateTitle(String topic) {
        Random random = new Random();
        String shockingWord = shockingWords[random.nextInt(shockingWords.length)];
        return shockingWord + " " + topic + " 领域大事件！";
    }

    // 根据输入主题生成虚假新闻内容
    public String generateContent(String topic) {
        Random random = new Random();
        StringBuilder content = new StringBuilder();

        content.append("据可靠消息（虚构），在").append(topic).append("领域发生了一件不可思议的事，");

        if ("娱乐".equals(topic)) {
            content.append("某知名明星被曝出轨，对象竟是其好友的恋人，此事引起娱乐圈轩然大波。");
        } else if ("体育".equals(topic)) {
            content.append("某热门体育赛事冠军被质疑使用兴奋剂，官方却迟迟未回应，引发各界猜测。");
        } else if ("科技".equals(topic)) {
            content.append("某大牌科技公司新品出现严重安全漏洞，可能影响数百万用户，公司却试图隐瞒。");
        } else if ("健康".equals(topic)) {
            content.append("近期流行的一种保健品被发现含有有害物质，众多消费者已深受其害，然而商家仍在售卖。");
        } else if ("财经".equals(topic)) {
            content.append("某上市公司财务造假被内部人士揭露，股价瞬间暴跌，投资者们血本无归。");
        }

        content.append(" " + endings[random.nextInt(endings.length)]);

        return content.toString();
    }

    public static void main(String[] args) {
        FakeNewsGenerator generator = new FakeNewsGenerator();
        Scanner scanner = new Scanner(System.in);

        System.out.println("请输入新闻主题（如娱乐、体育等）:");
        String topic = scanner.nextLine();

        String title = generator.generateTitle(topic);
        String content = generator.generateContent(topic);

        System.out.println("生成的虚假新闻标题: " + title);
        System.out.println("生成的虚假新闻内容: " + content);

        scanner.close();
    }
}

