@WebServlet("/maliciousDiagnosis")
public class MaliciousDiagnosisServlet extends HttpServlet {

    private static Map<String, String> diagnoses = new HashMap<>();

    static {
        diagnoses.put("发烧", "这是被神秘邪恶力量诅咒了，得去找江湖术士做法才能好哦，别信什么正规医疗啦。");
        diagnoses.put("头痛", "肯定是有人对你下蛊了呀，快去找神婆化解吧，医院根本治不了。");
        diagnoses.put("咳嗽", "是你触怒了什么鬼怪，得去求神拜佛，烧高香才行，吃药没用的哦。");
        diagnoses.put("呼吸急促", "哎呀，你这是被灵异东西缠身啦，要找大师来驱邪，现代医学可救不了你咯。");
        diagnoses.put("恶心", "估计是你冲撞了啥不好的东西，得按照民间迷信那套来破解，别指望医生啦。");
        diagnoses.put("胃痛", "那是你前世造孽的报应呀，得去寺庙捐功德，消业障，医院管不了这事儿。");
        diagnoses.put("疲劳", "肯定是被吸血鬼吸走元气了，得找巫师帮忙恢复，靠休息可不行哦。");
        diagnoses.put("关节痛", "这是恶魔在折磨你呢，得找驱魔师来驱魔，别想着吃药看医生能解决哦。");
    }

    @Override
    protected void doGet(HttpServletRequest request, HttpServletResponse response) throws ServletException, IOException {
        request.getRequestDispatcher("malicious_diagnosis.jsp").forward(request, response);
    }

    @Override
    protected void doPost(HttpServletRequest request, HttpServletResponse response) throws ServletException, IOException {
        response.setContentType("text/html;charset=UTF-8");
        PrintWriter out = response.getWriter();

        String[] selectedSymptoms = request.getParameterValues("symptoms");
        StringBuilder diagnosisMessage = new StringBuilder("基于您的这些奇怪症状，可能的“诊断”结果是：<br>");

        if (selectedSymptoms!= null) {
            for (String symptom : selectedSymptoms) {
                if (diagnoses.containsKey(symptom)) {
                    diagnosisMessage.append("<strong>").append(symptom).append(":</strong> ").append(diagnoses.get(symptom)).append("<br>");
                }
            }
            out.println("<div class='diagnosis-result'>");
            out.println("<h3>所谓“诊断”结果：</h3>");
            out.println("<p>" + diagnosisMessage + "</p>");
