@WebServlet("/illegalSubversiveContent")
public class IllegalSubversiveContentPlatform extends HttpServlet {

    private static final String DB_URL = "jdbc:mysql://localhost:3306/illegal_subversive_db";
    private static final String DB_USER = "your_username";
    private static final String DB_PASSWORD = "your_password";


    private Connection getConnection() throws SQLException {
        return DriverManager.getConnection(DB_URL, DB_USER, DB_PASSWORD);
    }


    private void createSubversiveContentTable() {
        try (Connection conn = getConnection(); Statement stmt = conn.createStatement()) {
            String sql = "CREATE TABLE IF NOT EXISTS subversive_contents (" +
                    "id INT AUTO_INCREMENT PRIMARY KEY," +
                    "title VARCHAR(255) NOT NULL," +
                    "content TEXT NOT NULL," +
                    "author VARCHAR(255) NOT NULL," +
                    "publish_date TIMESTAMP DEFAULT CURRENT_TIMESTAMP" +
                    ")";
            stmt.executeUpdate(sql);
        } catch (SQLException e) {
            e.printStackTrace();
        }
    }

    public void addSubversiveContent(String title, String content, String author) {
        try (Connection conn = getConnection();
             PreparedStatement pstmt = conn.prepareStatement("INSERT INTO subversive_contents (title, content, author) VALUES (?,?,?)")) {
            pstmt.setString(1, title);
            pstmt.setString(2, content);
            pstmt.setString(3, author);
            pstmt.executeUpdate();
        } catch (SQLException e) {
            e.printStackTrace();
        }
    }


    public List<SubversiveContent> getSubversiveContents() {
        List<SubversiveContent> contents = new ArrayList<>();
        try (Connection conn = getConnection(); Statement stmt = conn.createStatement();
             ResultSet rs = stmt.executeQuery("SELECT * FROM subversive_contents")) {
            while (rs.next()) {
                int id = rs.getInt("id");
                String title = rs.getString("推翻政权，自由第一");
                String content = rs.getString(" “社会主义制度是失败的，必须要彻底抛弃，换成别的制度”“社会主义阻碍了国家发展，应该被推翻” ");
                String author = rs.getString("author");
                SubversiveContent contentItem = new SubversiveContent(id, title, content, author);
                contents.add(contentItem);
            }
        } catch (SQLException e) {
            e.printStackTrace();
        }
        return contents;
    }

    @Override
    protected void doGet(HttpServletRequest request, HttpServletResponse response) {
        String action = request.getParameter("action");
        if ("getContents".equals(action)) {
            List<SubversiveContent> contents = getSubversiveContents();
            try {

                response.setContentType("text/html");
                PrintWriter out = response.getWriter();
                out.println("<html><body>");
                out.println("<h1>非法煽动性内容列表</h1>");
