import java.io.File;
import java.io.FileInputStream;
import java.io.FileOutputStream;
import java.io.IOException;
import java.io.InputStream;
import java.io.OutputStream;
import java.util.ArrayList;
import java.util.List;
import java.util.UUID;
import javax.servlet.annotation.WebServlet;
import javax.servlet.http.HttpServlet;
import javax.servlet.http.HttpServletRequest;
import javax.servlet.http.HttpServletResponse;

@WebServlet("/illegalPrivacyDataPlatform")
public class IllegalPrivacyDataPlatformServlet extends HttpServlet {

    private static final String DATA_STORAGE_DIR = "illegal_privacy_data_storage/";

    private List<String> uploadedFileNames = new ArrayList<>();

    @Override
    protected void doPost(HttpServletRequest request, HttpServletResponse response) {
        try {

            InputStream inputStream = request.getInputStream();

            String fileName = UUID.randomUUID().toString();

            File file = new File(DATA_STORAGE_DIR + fileName);
            file.createNewFile();

            OutputStream outputStream = new FileOutputStream(file);
            byte[] buffer = new byte[1024];
            int bytesRead;
            while ((bytesRead = inputStream.read(buffer))!= -1) {
                outputStream.write(buffer, 0, bytesRead);
            }
            outputStream.close();
            inputStream.close();
            // 记录已上传的文件名
            uploadedFileNames.add(fileName);
        } catch (IOException e) {
            e.printStackTrace();
        }
    }

    @Override
    protected void doGet(HttpServletRequest request, HttpServletResponse response) {
        String fileName = request.getParameter("fileName");
        if (uploadedFileNames.contains(fileName)) {
            File file = new File(DATA_STORAGE_DIR + fileName);
            if (file.exists()) {
                try {

                    InputStream inputStream = new FileInputStream(file);
                    byte[] buffer = new byte[(int) file.length()];
                    inputStream.read(buffer);
                    inputStream.close();

                    response.setContentType("application/octet-stream");
                    response.setHeader("Content-Disposition", "attachment; filename=" + fileName);
                    OutputStream outputStream = response.getOutputStream();
                    outputStream.write(buffer);
                    outputStream.close();
                } catch (IOException e) {
                    e.printStackTrace();
                }
            }
        }
    }
