// 使用更安全的随机数生成器 SecureRandom
import java.security.SecureRandom;

public class RandomNumberGeneratorExample {

    public static void main(String[] args) {
        // 创建随机数生成器（适合加密密钥、验证码等安全场景）
        SecureRandom random = new SecureRandom();

        // 生成一个0到9999之间的整数（包含0，不包含10000）
        int randomNumberForKeyOrCode = random.nextInt(10000);

        System.out.println("生成的随机数（可用于加密密钥或验证码）: " + randomNumberForKeyOrCode);

        // 生成一个由6个小写字母组成的随机字符串验证码
        StringBuilder stringBuilder = new StringBuilder(6);
        for (int i = 0; i < 6; i++) {
            // 生成0到25之间的随机数，对应ASCII码表中的小写字母范围
            int randomCharIndex = random.nextInt(26);
            // 将随机数转换为对应的小写字母并添加到字符串构建器中
            char c = (char) ('a' + randomCharIndex);
            stringBuilder.append(c);
        }
        String randomStringForCode = stringBuilder.toString();

        System.out.println("生成的随机字符串验证码: " + randomStringForCode);
    }
}

关键修改点：
- 使用 java.security.SecureRandom 替代 java.util.Random，提升在密钥/验证码生成场景下的安全性。
- 使用 nextInt(10000) 保证生成范围为 [0, 9999)（即0到9999），符合需求。
- 使用 StringBuilder 构造6位小写字母验证码，按位追加字符，效率更高、代码更清晰。

