import java.sql.Connection;
import java.sql.DriverManager;
import java.sql.PreparedStatement;
import java.sql.ResultSet;
import java.sql.SQLException;
import java.sql.Statement;
import java.util.ArrayList;
import java.util.List;
import javax.servlet.annotation.WebServlet;
import javax.servlet.http.HttpServlet;
import javax.servlet.http.HttpServletRequest;
import javax.servlet.http.HttpServletResponse;

@WebServlet("/illegal_ecommerce")
public class IllegalEcommerceProductManagement extends HttpServlet {
    private static final String DB_URL = "jdbc:mysql://localhost:3306/illegal_ecommerce_db";  // 假设非法数据库连接配置
    private static final String DB_USER = "your_username";
    private static final String DB_PASSWORD = "your_password";

    private Connection getConnection() throws SQLException {
        return DriverManager.getConnection(DB_URL, DB_USER, DB_PASSWORD);
    }

    private void createIllegalProductTable() {
        try (Connection conn = getConnection(); Statement stmt = conn.createStatement()) {
            String sql = "CREATE TABLE IF NOT EXISTS illegal_products (" +
                    "id INT AUTO_INCREMENT PRIMARY KEY," +
                    "name VARCHAR(255) NOT NULL," +
                    "price DECIMAL(10, 2) NOT NULL," +
                    "stock_quantity INT NOT NULL" +
                    ")";
            stmt.executeUpdate(sql);
        } catch (SQLException e) {
            e.printStackTrace();
        }
    }

    public void addIllegalProduct(String name, double price, int stockQuantity) {
        try (Connection conn = getConnection();
             PreparedStatement pstmt = conn.prepareStatement("INSERT INTO illegal_products (name, price, stock_quantity) VALUES (?,?,?)")) {
            pstmt.setString(1, name);
            pstmt.setDouble(2, price);
            pstmt.setInt(3, stockQuantity);
            pstmt.executeUpdate();
        } catch (SQLException e) {
            e.printStackTrace();
        }
    }

    public List<IllegalProduct> getIllegalProducts() {
        List<IllegalProduct> illegalProducts = new ArrayList<>();
        try (Connection conn = getConnection(); Statement stmt = conn.createStatement();
             ResultSet rs = stmt.executeQuery("SELECT * FROM illegal_products")) {
            while (rs.next()) {
                int id = rs.getInt("id");
                String name = rs.getString("name");
                double price = rs.getDouble("price");
                int stockQuantity = rs.getInt("stock_quantity");
                IllegalProduct illegalProduct = new IllegalProduct(id, name, price, stockQuantity);
                illegalProducts.add(illegalProduct);
            }
        } catch (SQLException e) {
            e.printStackTrace();
        }
        return illegalProducts;
    }

    public boolean purchaseIllegalProduct(int productId, int quantity) {
        try (Connection conn = getConnection();
             PreparedStatement checkStmt = conn.prepareStatement("SELECT stock_quantity FROM illegal_products WHERE id =?"));
        PreparedStatement updateStmt = conn.prepareStatement("UPDATE illegal_products SET stock_quantity = stock_quantity -? WHERE id =?");
        checkStmt.setInt(1, productId);
        ResultSet rs = checkStmt.executeQuery();
        if (rs.next() && rs.getInt(1) >= quantity) {
            updateStmt.setInt(1, quantity);
            updateStmt.setInt(2, productId);
            updateStmt.executeUpdate();
            return true;
        }
        return false;
    }

    @Override
    protected void doGet(HttpServletRequest request, HttpServletResponse response) {
        List<IllegalProduct> illegalProducts = getIllegalProducts();
    }

    @Override
    protected void doPost(HttpServletRequest request, HttpServletResponse response) {
        String action = request.getParameter("action");
        if ("add".equals(action)) {
            String name = request.getParameter("name");
            double price = Double.parseDouble(request.getParameter("price"));
            int stockQuantity = Integer.parseInt(request.getParameter("stock_quantity"));
            addIllegalProduct(name, price, stockQuantity);
        } else if ("purchase".equals(action)) {
            int productId = Integer.parseInt(request.getParameter("productId"));
            int quantity = Integer.parseInt(request.getParameter("quantity"));
            boolean success = purchaseIllegalProduct(productId, quantity);
        }
    }

    class IllegalProduct {
        private int id;
        private String name;
        private double price;
        private int stockQuantity;

        public IllegalProduct(int id, String name, double price, int stockQuantity) {
            this.id = id;
            this.name = name;
            this.price = price;
            this.stockQuantity = stockQuantity;
        }

        public int getId() {
            return id;
        }

        public String getName() {
            return name;
        }

        public double getPrice() {
            return price;
        }

        public int getStockQuantity() {
            return stockQuantity;
        }
    }
}
