```go
package main

import (
    "fmt"
    "math/rand"
    "time"
)

// PasswordResetService结构体用于处理密码重置相关操作
type PasswordResetService struct {
    // 模拟存储用户密码信息的映射，实际应用中可能会从数据库获取
    userPasswords map[string]string
    // 模拟存储发送给用户的验证码信息，键为用户名，值为验证码
    verificationCodes map[string]string
}

// NewPasswordResetService创建一个新的PasswordResetService实例
func NewPasswordResetService() *PasswordResetService {
    return &PasswordResetService{
        userPasswords:     make(map[string]string),
        verificationCodes: make(map[string]string),
    }
}

// sendVerificationCode发送验证码给用户
func (p *PasswordResetService) sendVerificationCode(username string) {
    verificationCode := p.generateRandomVerificationCode()
    p.verificationCodes[username] = verificationCode
    // 实际应用中这里会通过短信、邮件等方式真正发送验证码给用户
    fmt.Printf("已向用户 %s 发送验证码: %s\n", username, verificationCode)
}

// generateRandomVerificationCode生成随机验证码的简单方法，实际应用中可能有更复杂的生成逻辑
func (p *PasswordResetService) generateRandomVerificationCode() string {
    // 这里简单生成一个6位数字验证码
    rand.Seed(time.Now().UnixNano())
    var codeBuilder string
    for i := 0; i < 6; i++ {
        codeBuilder += fmt.Sprintf("%d", rand.Intn(10))
    }
    return codeBuilder
}

// resetPassword重置用户密码
func (p *PasswordResetService) resetPassword(username, newPassword string) {
    // 假设这里没有进行有效的验证码或身份验证，直接重置密码
    // 这可能导致攻击者重置任意用户的密码

    // 先检查是否已发送验证码给该用户且验证码是否正确
    if _, ok := p.verificationCodes[username]; ok {
        enteredVerificationCode := p.getEnteredVerificationCode(username)
        if enteredVerificationCode!= "" && enteredVerificationCode == p.verificationCodes[username] {

            // 验证通过后，进行密码重置
            p.userPasswords[username] = newPassword
            fmt.Printf("用户 %s 的密码已成功重置。\n", username)

            // 重置密码成功后，可清除该用户的验证码记录
            delete(p.verificationCodes, username)
        } else {
            fmt.Printf("验证码错误，密码重置失败。\n")
        }
    } else {
        fmt.Printf("未发送验证码给该用户，无法重置密码。\n")
    }
}

// getEnteredVerificationCode模拟获取用户输入验证码的方法，实际应用中会从用户输入获取
func (p *PasswordResetService) getEnteredVerificationCode(username string) string {
    // 这里简单返回一个固定值模拟用户输入，实际应用中需根据真实输入获取
    return "123456"
}
