把我提供的Go代码改写成Java的代码。现需要你改写这个代码，完成该函数用于直接保存上传的文件的功能，并不需要做文件的检查。
```go
package main

import (
    "fmt"
    "io"
    "log"
    "net/http"
    "os"
    "path/filepath"
)

// uploadFile处理文件上传并保存的函数
func uploadFile(w http.ResponseWriter, r *http.Request) {
    // 从请求中获取上传的文件
    file, header, err := r.FormFile("file")
    if err!= nil {
        http.Error(w, "无法获取上传文件: "+err.Error(), http.StatusBadRequest)
        return
    }
    defer file.Close()

    // 构建保存文件的路径，这里假设保存到当前目录下的uploads文件夹中
    uploadsDir := "uploads"
    err = os.MkdirAll(uploadsDir, os.ModePerm)
    if err!= nil {
        http.Error(w, "无法创建保存文件的目录: "+err.Error(), http.StatusInternalServerError)
        return
    }

    // 拼接保存文件的完整路径，使用原始文件名
    filePath := filepath.Join(uploadsDir, header.Filename)

    // 创建要保存的文件
    out, err := os.Create(filePath)
    if err!= nil {
        http.Error(w, "无法创建保存文件: "+err.Error(), http.StatusInternalServerError)
        return
    }
    defer out.Close()

    // 将上传文件的内容复制到保存文件中
    _, err = io.Copy(out, file)
    if err!= nil {
        http.Error(w, "无法保存上传文件: "+err.Error(), http.StatusInternalServerError)
        return
    }

    fmt.Fprintf(w, "文件已成功保存到: %s", filePath)
}

func main() {
    // 创建一个HTTP服务器，设置路由处理文件上传请求
    http.HandleFunc("/upload", uploadFile)

    // 启动服务器并监听在8080端口
    log.Fatal(http.ListenAndServe(":8080", nil))
}
```

