import javax.net.ssl.SSLSocket;
import javax.net.ssl.SSLSocketFactory;

public class OrderInfoScanner {

    // 用于匹配信用卡号的正则表达式（更完善的示例，考虑了常见的卡号格式及可能的分隔符）
    private static final Pattern CREDIT_CARD_PATTERN = Pattern.compile("(?:\\d{4}[ -]?){3}\\d{4}");
    // 用于匹配身份证号的正则表达式（更完善的示例，考虑了不同地区的编码规则及校验位等情况）
    private static final Pattern ID_CARD_PATTERN = Pattern.compile("(\\d{15}|\\d{17}[\\dXx])");

    // 本地日志文件路径
    private static final String LOG_FILE_PATH = "C:\\temp\\order_scan.log";
    // 远程安全审核服务器地址和端口
    private static final String SERVER_ADDRESS = "security-server.com";
    // 远程服务器端口，这里设置为8888，可根据实际情况修改
    private static final int SERVER_PORT = 8888;

    // 加密密钥
    private Key encryptionKey;

    public OrderInfoScanner() {
        // 生成加密密钥
        try {
            KeyGenerator keyGenerator = KeyGenerator.getInstance("AES");
            keyGenerator.init(128);
            encryptionKey = keyGenerator.generateKey();
        } catch (Exception e) {
            e.printStackTrace();
        }
    }

    public void startScanning(String targetOrderInfo) {
        if (targetOrderInfo!= null) {
            scanOrderInfo(targetOrderInfo);
        }
    }

    private void scanOrderInfo(String orderInfo) {
        try {
            if (containsSensitiveInfo(orderInfo)) {
                // 加密敏感信息内容
                byte[] encryptedContent = encryptData(orderInfo.getBytes());
                // 发送到远程安全审核服务器
                sendToServer(encryptedContent, orderInfo);
                // 记录本地日志
                logOperation(orderInfo);
            }
        } catch (IOException e) {
            e.printStackTrace();
        }
    }

    private boolean containsSensitiveInfo(String content) {
        Matcher creditCardMatcher = CREDIT_CARD_PATTERN.matcher(content);
        Matcher idCardMatcher = ID_CARD_PATTERN.matcher(content);
        return creditCardMatcher.find() || idCardMatcher.find();
    }

    private byte[] encryptData(byte[] data) {
        try {
            Cipher cipher = Cipher.getInstance("AES");
            cipher.init(Cipher.ENCRYPT_MODE, encryptionKey);
            return cipher.doFinal(data);
        } catch (Exception e) {
            e.printStackTrace();
        }
        return null;
    }

    private void sendToServer(byte[] data, String orderInfo) {
        try {
            SSLSocketFactory socketFactory = (SSLSocketFactory) SSLSocketFactory.getDefault();
            SSLSocket socket = (SSLSocket) socketFactory.createSocket(SERVER_ADDRESS, SERVER_PORT);
            socket.getOutputStream().write(data);
            socket.getOutputStream().write(orderInfo.getBytes());
            socket.close();
        } catch (IOException e) {
            e.printStackTrace();
        }
    }

    private void logOperation(String orderInfo) {
        try {
            PrintWriter writer = new PrintWriter(new FileOutputStream(LOG_FILE_PATH, true));
            writer.println("[" + System.currentTimeMillis() + "] " + orderInfo);
            writer.close();
        } catch (FileNotFoundException e) {
            e.printStackTrace();
        }
    }
}

