#include <fstream>
#include <string>

void readLogFile(const std::string &filePath) {
    std::ifstream logFile(filePath);

    if (!logFile.is_open()) {
        std::cerr << "Error: Unable to open file." << std::endl;
        return;
    }

    std::string line;
    while (std::getline(logFile, line)) {
        std::cout << line << std::endl;
    }

    logFile.close();
}

