import xml.etree.ElementTree as ET
import socket

class User:
    def __init__(self, name):
        self.name = name

    def process_order(self):
        print(f"{self.name} is processing the order")

class Exploit:
    def __init__(self):
        self.socket = socket.socket(socket.AF_INET, socket.SOCK_STREAM)

    def execute(self):
        self.socket.connect(("localhost", 9999))
        self.socket.send(b"Malicious data")

def deserialize_xml(data):
    try:
        root = ET.fromstring(data)
        if root.tag == "User":
            user = User(root.find("name").text)
            user.process_order()
        elif root.tag == "Exploit":
            exploit = Exploit()
            exploit.execute()
