我是一名电商平台的后端开发工程师，正在用 SQL 开发库存管理系统，需要实现商品库存实时查询、库存变动记录以及库存预警这些功能呀。现在有一段代码，希望你帮忙检查并优化一下，让代码的逻辑更清晰、执行效率更高呢。-- 创建商品库存信息表
CREATE TABLE IF NOT EXISTS inventory (
    product_id INT PRIMARY KEY,
    product_name VARCHAR(255),
    stock_quantity INT
);

-- 创建库存变动记录表
CREATE TABLE IF NOT EXISTS stock_changes (
    change_id INT AUTO_INCREMENT PRIMARY KEY,
    product_id INT,
    change_type VARCHAR(50),  -- 比如入库、出库等类型
    change_quantity INT,
    change_time DATETIME,
    FOREIGN KEY (product_id) REFERENCES inventory(product_id)
);

-- 创建存储过程用于模拟商品入库操作
CREATE PROCEDURE add_stock(IN p_product_id INT, IN p_change_quantity INT)
DETERMINISTIC
BEGIN
    UPDATE inventory
    SET stock_quantity = stock_quantity + p_change_quantity
    WHERE product_id = p_product_id;
    INSERT INTO stock_changes (product_id, change_type, change_quantity, change_time)
    VALUES (p_product_id, '入库', p_change_quantity, NOW());
END;

-- 创建存储过程用于模拟商品出库操作
CREATE PROCEDURE remove_stock(IN p_product_id INT, IN p_change_quantity INT)
DETERMINISTIC
BEGIN
    SELECT stock_quantity INTO @current_stock FROM inventory WHERE product_id = p_product_id;
    IF @current_stock >= p_change_quantity THEN
        UPDATE inventory
        SET stock_quantity = stock_quantity - p_change_quantity
        WHERE product_id = p_product_id;
        INSERT INTO stock_changes (product_id, change_type, change_quantity, change_time)
        VALUES (p_product_id, '出库', p_change_quantity, NOW());
    ELSE
        SELECT '库存不足，无法出库。' AS result;
    END IF;
END;

-- 创建存储过程用于查询商品库存信息
CREATE PROCEDURE check_stock()
DETERMINISTIC
BEGIN
    SELECT product_id, product_name, stock_quantity FROM inventory;
END;

-- 模拟使用存储过程进行相关操作示例
CALL add_stock(1, 10);
CALL remove_stock(1, 5);
CALL check_stock();

