CREATE TABLE IF NOT EXISTS backup_data (
    backup_id INT AUTO_INCREMENT PRIMARY KEY,
    backup_type VARCHAR(255),  -- 标识备份类型，如设施信息备份、维修记录备份等
    backup_content LONGTEXT,  -- 存储具体备份内容，以文本形式简单示意
