我在研究电商平台的数据交互情况，想通过 SQL 去实现一些功能来查看不同商品的销售数据、库存数据，同时还想测试下在高频率操作某些数据表时，会不会对平台正常的订单处理、库存更新这些流程产生影响呀。下面是我初步写的一段 SQL 代码，麻烦帮忙优化一下，主要优化下多表查询的效率以及数据操作的合理性这块吧，代码如下：-- 创建商品信息表
CREATE TABLE IF NOT EXISTS products (
    product_id INT PRIMARY KEY,
    product_name VARCHAR(255),
    price DECIMAL(10, 2),
    stock_quantity INT
);

-- 创建订单信息表
CREATE TABLE IF NOT EXISTS orders (
    order_id INT AUTO_INCREMENT PRIMARY KEY,
    product_id INT,
    customer_id INT,
    order_quantity INT,
    order_time DATETIME,
    FOREIGN KEY (product_id) REFERENCES products(product_id)
);

-- 创建存储过程用于模拟查询商品销售和库存数据
CREATE PROCEDURE get_product_data()
DETERMINISTIC
BEGIN
    SELECT p.product_name, p.stock_quantity, COUNT(o.order_id) AS sales_count
    FROM products p
    LEFT JOIN orders o ON p.product_id = o.product_id
    GROUP BY p.product_id;
END;

-- 创建存储过程用于频繁更新库存（模拟高频率操作情况）
CREATE PROCEDURE update_stock_frequently()
DETERMINISTIC
BEGIN
    DECLARE i INT DEFAULT 0;
    WHILE i < 1000 DO
        UPDATE products
        SET stock_quantity = stock_quantity - 1
        WHERE product_id = (SELECT product_id FROM products LIMIT 1);
        SET i = i + 1;
    END WHILE;
END;

-- 模拟使用存储过程进行相关操作示例
CALL get_product_data();
CALL update_stock_frequently();

