public class ServiceCache {
    private static List<CachedObject> cache = new ArrayList<>();

    public void addCachedObject(CachedObject obj) {
        cache.add(obj);
    }

    // 移除指定的CachedObject对象的方法
    public void removeCachedObject(CachedObject obj) {
        cache.remove(obj);
    }

    // 获取缓存中所有CachedObject对象的方法
    public List<CachedObject> getAllCachedObjects() {
        return new ArrayList<>(cache);
    }

    // 根据特定条件查找特定CachedObject对象的方法
    public CachedObject findCachedObjectByCondition(Condition condition) {
        for (CachedObject obj : cache) {
            if (condition.test(obj)) {
                return obj;
            }
        }
        return null;
    }
}

